import{_ as t,c as e,a2 as a,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"为人处世如何才能大大方方，不扭扭捏捏？","description":"","frontmatter":{},"headers":[],"relativePath":"技能/为人处世如何才能大大方方，不扭扭捏捏.md","filePath":"技能/为人处世如何才能大大方方，不扭扭捏捏.md"}'),r={name:"技能/为人处世如何才能大大方方，不扭扭捏捏.md"};function o(n,p,s,c,i,d){return _(),e("div",null,p[0]||(p[0]=[a('<h1 id="为人处世如何才能大大方方-不扭扭捏捏" tabindex="-1">为人处世如何才能大大方方，不扭扭捏捏？ <a class="header-anchor" href="#为人处世如何才能大大方方-不扭扭捏捏" aria-label="Permalink to &quot;为人处世如何才能大大方方，不扭扭捏捏？&quot;">​</a></h1><p>你找错方向了。什么自卑、没见过世面、长得不美，这些都是表象，甚至是自欺欺人的借口。真正的结，不在这儿。</p><p>所谓大大方方，根本不是性格或者自信的问题，它是一种你对空间和关系的默认权限设定。</p><p><strong>扭扭捏捏的根源，在于你潜意识里，把自己当成了进入他人空间的访客，而不是那个空间理所当然的共同拥有者，甚至主人</strong>。</p><p>你想想，你在朋友面前为什么放得开？因为那个场子，你默认有你的一份。</p><p>你笑、你闹、你说错话，你潜意识里知道这地盘有你的股份，你的存在是被接纳的，你不是来申请许可的。</p><p>但在工作场合，尤其面对领导和陌生人，你的默认设定变了。你把自己切换到了访客模式，或者更糟，是申请进入许可的模式。</p><p>你的全部注意力，都放在了揣摩主人的脸色，遵守你想象中的规则，生怕自己哪个动作不合规矩，就被驱逐出境，或者被打上差评。</p><p>你的能量，全耗在自我审查和对他人反应的过度解读上。这种状态，怎么可能不扭捏？</p><p>你像一个站在别人家客厅里，手都不知道往哪儿放的远房穷亲戚。 所以，你真正要改变的，不是去学什么狗屁沟通技巧，不是去强行假装自信，那些都是术的层面，是缘木求鱼。</p><p>你要改的是那个底层的权限设定。 从现在开始，在任何场合，都默认这个空间有你的一份。 你不是来被审视、被评价、被批准的。你是来占用你那份空气，发出你的声音，贡献你的价值，或者仅仅是，存在。 你的存在本身，就是你的资格证。 领导也好，陌生人也罢，他们也是这个空间的使用者，跟你一样，不多也不少。</p><p>他们的评价，只是他们视角下的信息，不代表最终裁决，更不决定你在这个空间里的合法性。</p><p>当你内心深处，真正把自己从那个战战兢兢的访客，调整为理直气壮的共同所有者时，你会发现你的注意力会从自我监控，转向外部现实。</p><p>你开始关注事情本身，而不是你看起来怎么样。</p><p>而且你对负面反馈的敏感度会大幅降低。 因为你不再需要他们的批准来确认你的存在价值。</p><p>批评只是信息，不是审判。姿态会自然舒展。</p><p>因为你不再需要蜷缩自己去适应别人，你只是在你自己的（共享）空间里正常活动。这跟你有多少钱，见过多少世面，长什么样，关系不大。</p><p>我见过身价不菲但依然拘谨的人，也见过出身平凡但气场十足的。区别就在于，后者默认了自己对所处空间的拥有权。</p><p>别再向外求了。大大方方是你与生俱来的权限，是你自己把它关了。</p><p>现在，把它重新打开。 这不是让你去嚣张跋扈，而是让你找回一种基本的、内在的、不依附于任何外在条件的从容。</p><p>下次再觉得扭捏时，问自己一句：我在谁的地盘上？答案永远是：也包括我的。</p>',21)]))}const f=t(r,[["render",o]]);export{m as __pageData,f as default};
